import{_ as t,o as r,c as a,ak as n}from"./chunks/framework.B8jO0odJ.js";const m=JSON.parse('{"title":"Chainy current project baseline","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","frontmatter":{"title":"Chainy current project baseline","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","source":"docs/archive/pre-v2-adoption-2026-10-23/docs/project-baseline.md","category":"Archive","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/project-baseline.md","filePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/project-baseline.md"}'),i={name:"content/docs/archive/pre-v2-adoption-2026-10-23/docs/project-baseline.md"};function o(s,e,d,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[n('<div><h1 id="chainy-current-project-baseline">Chainy current project baseline<a class="header-anchor" href="#chainy-current-project-baseline" aria-label="Link to this section">​</a></h1><blockquote><p>Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/readme.html">adoption archive</a>.</p></blockquote><p>Updated October 22, 2026. Decision owner: Sherwin Limosnero. Technical design owner: Christian Jude Villaber.</p><p><strong>Capstone title:</strong> Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain &amp; AI)</p><h2 id="governing-mission-and-scope">Governing mission and scope<a class="header-anchor" href="#governing-mission-and-scope" aria-label="Link to this section">​</a></h2><p>Build an offline Android game that introduces foundational Web3, Blockchain and AI concepts to learners aged 12–17, especially learners in low-income and remote communities with limited technology access. English remains the first language.</p><p>The user has explicitly replaced the earlier generated gameplay plan with <a href="/Chainy-Docs/content/docs/archive/source-material/technical-design-christian-2026-10-12.html">Christian&#39;s technical design</a>. The current gameplay uses explorable 3D levels, learning interactions/dialogue, <strong>Quiz, Wordle and BlockMatch</strong>. Only one mini-game runs at a time. SQLite stores local profiles, learning content and progress.</p><p>The subject areas remain learning content; they do not require the old nine-lesson map or a fixed world/level count. Sherwin and Sean will map topics to the three mini-games. The old mandatory record-ordering, three-copy simulation, example-trained classifier and grid-agent implementations are withdrawn. Teaching about AI does not require implementing an AI model in the game.</p><h2 id="confirmed-decisions">Confirmed decisions<a class="header-anchor" href="#confirmed-decisions" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Decision</th><th>Current position</th></tr></thead><tbody><tr><td>Governing technical source</td><td>Christian&#39;s supplied design, adopted by direct user instruction October 12</td></tr><tr><td>Gameplay</td><td>Explorable levels, Quiz, Wordle, BlockMatch; exact level count and game rules still need the team&#39;s short content/rules sheet</td></tr><tr><td>Runtime</td><td>Single-player Unity/C#, touch controls on Android; pointer/keyboard may support development</td></tr><tr><td>Local storage</td><td>SQLite; JSON may be an export format, not the save database</td></tr><tr><td>Connectivity</td><td>Gameplay and saving operate locally; no backend, cloud service or external authentication in this architecture</td></tr><tr><td>Profile</td><td>A learner code selects a local profile; it does not verify identity or restore another device&#39;s progress</td></tr><tr><td>Visual direction</td><td>Fixed orthographic isometric camera and restrained low-poly world treatment, using the supplied Tunic screenshots for camera/material/composition reference without copying protected assets; retain Chainy&#39;s blue-haired yellow-clad Explorer and screen-faced robot identity in the new low-poly treatment</td></tr><tr><td>Dialogue presentation</td><td>Dialogue remains a UI overlay on the live isometric 3D world: dialogue at the bottom, choices in the middle, Explorer and speaker portraits at the left and right; world controls are disabled while the overlay is active</td></tr><tr><td>Team</td><td>Sherwin: Project and Design Lead; Christian: Tech Lead; Luis: Art Lead; Sean: Docs Lead; Miguel: UI support</td></tr><tr><td>Role boundaries</td><td>One owner per card: Sherwin makes project/design decisions; Christian owns game code, data, builds and technical integration; Luis owns art assets; Sean alone authors project documents; Miguel owns game UI implementation. Separate cross-role handoffs instead of assigning helpers/reviewers.</td></tr><tr><td>Documentation</td><td>Sean is the sole project-document author. Write for beginner-to-intermediate project-management readers; keep engineering detail in the technical reference. Christian supplies/reviews technical facts; Sherwin decides learner experience.</td></tr><tr><td>Beta</td><td><strong>November 3–6, 2026, fixed</strong>, at Tambunan National High School, Marinduque</td></tr><tr><td>Pre-final</td><td><strong>November 21, 2026, fixed</strong></td></tr><tr><td>Management</td><td>The Chainy team board edits shared tasks and records named history; GitHub issues receive an execution copy; backlog.json is the publication inventory; Trello is retired. Each teammate uses an individual account and must replace the shared temporary first-use password <code>123</code> before editing so audit history can identify them.</td></tr></tbody></table><p>Fixed event dates do not establish that permissions, participant arrangements, travel or devices are ready. Sherwin owns coordination and decisions; Sean records approved requirements and evidence in project documents. The broader September 2026–April 2027 cycle remains.</p><h2 id="current-implementation-evidence">Current implementation evidence<a class="header-anchor" href="#current-implementation-evidence" aria-label="Link to this section">​</a></h2><p>The user says Christian wrote and verified the supplied design. Part VI reports:</p><table><thead><tr><th>Component</th><th>Reported state</th><th>Evidence named in the source</th></tr></thead><tbody><tr><td>SQLite schema and data connection</td><td>In progress</td><td>DatabaseManager.cs</td></tr><tr><td>Local learner profile</td><td>In progress</td><td>ProfileController.cs creates local records; input validation remains</td></tr><tr><td>Player controller</td><td>Completed</td><td>Working 3D movement and collision handling; speed/rotation checks remain</td></tr><tr><td>Quiz</td><td>In progress</td><td>Question UI reads ScriptableObjects; score-to-database connection remains</td></tr><tr><td>BlockMatch</td><td>Not started</td><td>Matching scripts folder; modular system remains</td></tr><tr><td>Wordle</td><td>Not started</td><td>No evidence listed</td></tr><tr><td>UI</td><td>In progress</td><td>Main menu and gameplay UI</td></tr><tr><td>Models</td><td>In progress</td><td>Player and world objects; level design remains</td></tr></tbody></table><p>This replaces the October 8 zero-progress report. It does not prove Android acceptance, persistence reliability or completion of an entire CH task. Attach the actual build/source reference and test result before marking an issue Done.</p><h2 id="delivery-boundary">Delivery boundary<a class="header-anchor" href="#delivery-boundary" aria-label="Link to this section">​</a></h2><p>There are 22 calendar days from October 12 to beta start, and 40 to pre-final. Actual available hours by member remain unknown. The old 520-hour allocation is archived; it is not a budget proven for this replacement scope.</p><p>Scope verdict: <strong>validate first</strong>. Finish one complete Quiz → save → reload loop, then reuse its shared systems for Wordle and BlockMatch. Keep levels compact and reuse assets. A new framework, extra game mode or large world consumes the same time needed for integration and testing.</p><p>Local planning targets: working first loop October 18; remaining modes and teacher collection October 25; integrated candidate October 30; device checks October 31–November 2; fixed beta November 3–6; fixes/results November 7–13; manuscript November 16; rehearsal November 17–20. These are targets, not measured capacity or school approval. The split task plan retains them.</p><p>If a target fails, Sherwin must resolve the impact with the team/site/adviser. Do not silently move fixed dates, remove a required mode or turn the testing period into feature development.</p><h2 id="school-requirements">School requirements<a class="header-anchor" href="#school-requirements" aria-label="Link to this section">​</a></h2><p>Pre-final requires functional core modules, completed manuscript chapters and necessary pilot-area evidence/documents. The supplied quality rubric has eight unnamed criteria scored 1–4, totalling 32. The school also requires 60 percent completion, but its calculation and criterion meanings remain unknown. Task counts and quality-rating bands cannot establish that percentage.</p><p>The <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/manuscript-evidence-map.html">official manuscript outline</a>, including appendices A–M and the unresolved school phrase “ISO 2010,” is retained. Report actual preliminary and system evaluation evidence; do not invent results.</p><h2 id="device-target">Device target<a class="header-anchor" href="#device-target" aria-label="Link to this section">​</a></h2><p>Retain Android 10+/11+, 4 GB physical RAM, 64 GB total device storage, ARM64, OpenGL ES 3.2 or Vulkan 1.1, and an entry-level-to-midrange GPU. Android 11+ remains the provisional test interpretation and Android 10 a compatibility candidate. These are target specifications, not measured support. See <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/hardware-validation.html">device checks</a>.</p><h2 id="decisions-still-needed">Decisions still needed<a class="header-anchor" href="#decisions-still-needed" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Item</th><th>Owner</th><th>Required answer or artifact</th></tr></thead><tbody><tr><td>Rules and content</td><td>Sherwin + Sean, Christian review</td><td>Quiz scoring/pass rule; Wordle dictionary/attempts/repeated-letter rules; BlockMatch objective/moves/end rule; one concept and explanation for each</td></tr><tr><td>Save/data details</td><td>Christian + Sean</td><td>Actual SQLite schema; learner-code type; meaning of score/percentage/attempt; progress versus attempt history; any research need for age/name</td></tr><tr><td>Source conflicts</td><td>Christian</td><td>Resolve Score Manager/Dialogue Manager references, SQL ownership and SQLite versus ScriptableObject content boundary</td></tr><tr><td>Build source</td><td>Christian</td><td>Confirm Unity Cloud versus Chainy-Game working source, revision, Unity version and Android build steps</td></tr><tr><td>Delivery readiness</td><td>Sherwin + Sean</td><td>Member availability, devices, school requirements, site arrangements and approved evaluation instruments</td></tr></tbody></table><p>The user confirmed that exact Quiz, Wordle and BlockMatch rules are not yet agreed; CH-02 is the first joint Design/Tech task. These are bounded decisions on existing tasks, not additional project phases. No participant records, identity maps, credentials or signing keys belong in this repository or issues.</p><h2 id="traceable-requirements">Traceable requirements<a class="header-anchor" href="#traceable-requirements" aria-label="Link to this section">​</a></h2><p>The <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/requirements/product-requirements.html">current acceptance checklist</a> defines new TD-R01–10 IDs. Old CH-R01–12 are preserved in the archived October 8 documents and the archived backlog; their meanings are not reused for different mechanics. Current task cards explicitly use the replacement scope.</p><h2 id="publication-and-tooling">Publication and tooling<a class="header-anchor" href="#publication-and-tooling" aria-label="Link to this section">​</a></h2><p>The <a href="/Chainy-Docs/content/tools/docs-viewer/readme.html">documentation viewer</a> and <a href="/Chainy-Docs/content/docs/team-board-guide.html">team board</a> are management tools, separate from offline gameplay. Five individual team accounts share the live Kanban and Gantt views. The board stores changes and audit history in the existing Cloudflare service; GitHub Pages serves the interface.</p><p>The October 12 cutover preserves the 26 existing GitHub issue links and the inspected Todo states. It replaces their old descriptions, assignments, dates and dependencies with this plan. The team board is the editing interface; queued copies keep GitHub issues aligned. Trello webhooks and synchronization are retired. A task count is never the school’s completion percentage.</p></div>',1)])])}const u=t(i,[["render",o]]);export{m as __pageData,u as default};
